  --color-error-fg:   #F1707A;       /* Failed */
  --color-info-bg:    #0A2740;
  --color-info-fg:    #4FB0F5;

  /* Surface */
  --bg-base:     #1F1F1F;
  --bg-subtle:   #292929;
  --bg-elevated: #2E2E2E;
  --bg-header:   #0E1726;
  --bg-sidebar:  #262626;
  --bg-overlay:  rgba(0,0,0,0.60);

  /* Text */
  --text-primary:    #F3F2F1;
  --text-secondary:  #D2D0CE;
  --text-tertiary:   #A6A4A2;
  --text-link:       #4FB0F5;
  --text-link-hover: #A8D9FB;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #6E6C6A;

  /* Border */
  --border-default: #484644;
  --border-subtle:  #3B3A39;
  --border-strong:  #6E6C6A;
  --border-focus:   #2B9CF0;
}

