.btn { font: 600 13px/1 'Segoe UI Variable', 'Segoe UI', sans-serif; letter-spacing: -0.005em;
       border-radius: 2px; padding: 7px 14px; border: 1px solid transparent;
       display: inline-flex; align-items: center; justify-content: center; gap: 6px; }
.btn-primary { background: var(--color-primary-500); color: #fff; }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { background: var(--color-primary-700); }
.btn-secondary { background: var(--bg-elevated); color: var(--text-primary); border-color: var(--border-default); }
.btn-secondary:hover { background: var(--bg-subtle); }
.btn-subtle { background: transparent; color: var(--text-primary); }
.btn-subtle:hover { background: var(--bg-subtle); }
.btn-danger { background: var(--color-error-fg); color: #fff; }
.input { background: var(--bg-elevated); border: 1px solid var(--border-default); border-bottom-width: 2px; border-bottom-color: var(--text-tertiary); border-radius: 2px; padding: 6px 10px; font: 400 13px/1.4 inherit; color: var(--text-primary); }
.input:focus { outline: 0; border-bottom-color: var(--color-primary-500); }
.input-code { font: 400 13px/1.4 'Cascadia Mono', monospace; }
.card { background: var(--bg-elevated); border: 1px solid var(--border-default); padding: 12px 14px; box-shadow: var(--shadow-2); border-radius: 0; }
.table { background: var(--bg-elevated); border: 1px solid var(--border-default); }
.table .head { display: grid; grid-template-columns: 1fr 100px 120px 100px 80px; background: var(--bg-subtle); border-bottom: 1px solid var(--border-default); padding: 8px 12px; gap: 10px; font: 600 11px/1.4 inherit; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.04em; }
.table .row { display: grid; grid-template-columns: 1fr 100px 120px 100px 80px; padding: 9px 12px; gap: 10px; border-bottom: 1px solid var(--border-subtle); font: 400 13px/1.4 inherit; align-items: center; }
.table .row:last-child { border-bottom: 0; }
.table .row:hover { background: var(--color-primary-50); }
.table .row .name { color: var(--text-link); font-weight: 600; cursor: pointer; }
.table .row .name:hover { text-decoration: underline; }
.table .row .meta { font: 400 11px/1.3 inherit; color: var(--text-tertiary); margin-top: 1px; }
.table .row .mono { font: 400 12px/1.4 'Cascadia Mono', monospace; color: var(--text-primary); }
.status { padding: 1px 8px; border-radius: 0; font: 600 11px/1.4 inherit; display: inline-flex; align-items: center; gap: 4px; }
.status::before { content: '●'; font-size: 9px; }
.status-running { color: var(--color-success-fg); }
.status-stopped { color: var(--text-tertiary); }
.status-failed  { color: var(--color-error-fg); }
.tag { padding: 2px 8px; border-radius: 2px; font: 600 11px/1.4 inherit; }
.tag-resource { background: var(--color-info-bg); color: var(--color-info-fg); }
.tag-preview  { background: var(--color-warning-bg); color: #C8B560; }
.navbar { background: var(--bg-header); color: #fff; padding: 0 14px; display: flex; align-items: center; gap: 12px; height: 40px; }
.navbar .logo { font: 600 14px/1 'Segoe UI Variable', sans-serif; letter-spacing: -0.005em; }
.navbar .search { flex: 1; max-width: 480px; background: rgba(255,255,255,0.10); border-radius: 2px; padding: 6px 10px; font: 400 12px/1.4 inherit; color: var(--text-on-primary); }
.navbar .right { margin-left: auto; display: flex; align-items: center; gap: 12px; font: 400 12px/1.4 inherit; color: #fff; }
.sidebar { background: var(--bg-sidebar); border-right: 1px solid var(--border-default); padding: 8px 0; width: 200px; }
.sidebar .head { padding: 6px 14px; font: 600 11px/1.4 inherit; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.04em; }
.sidebar .item { padding: 7px 14px; font: 500 12px/1.4 inherit; color: var(--text-primary); cursor: pointer; display: flex; align-items: center; gap: 8px; border-left: 2px solid transparent; }
.sidebar .item:hover { background: var(--bg-base); }
.sidebar .item.active { background: var(--color-primary-50); color: var(--color-primary-700); border-left-color: var(--color-primary-500); padding-left: 12px; }
